expected.fmt:
import (
    Key, Cause from "./domain.ms",
    transform_set,
    locate_map,
    locate_set,
    convert,
    remap_keys,
    remap_values from "./helpers.ms",
)

impl Equal for Key:
    fn equals(other: Key) Bool:
        return self.label == other.label

impl Hashable for Key:
    fn hash() Int: self.label.scalar_length()

fn second_cause(cause: Cause) Error: Error("second {cause.count}")

export fn second_mapped() Set[Key]:
    values := Set[Int]([1, 2])
    return transform_set(values, fn n: Key(0, n.to_string()))

export fn second_failure(cause: Cause) String!:
    value: Int! = error(second_cause(cause))
    return value.and_then(fn n: Result[String, Error].ok(n.to_string()))

export fn second_queries() Bool:
    key := Key(5, "original")
    var map = Map[Key, String]()
    map.add(key.clone(), "found")

    set := Set[Key]([key])
    return (
        locate_map(map, Key(5, "different")).is_none()
        and locate_set(set, Key(5, "different")).is_none()
    )

export fn second_converted(cause: Cause) Int!:
    missing: Int? = none
    return convert(missing, fn() Error: second_cause(cause))

export fn second_folded(cause: Cause) Error:
    var values = Map[String, Int]()
    values.add("key", 1)
    return values.fold[Error](second_cause(cause), fn acc, key, value: acc)

export fn second_key_transform[T: Hashable](input: Map[T, Int]) Map[Key, Int]:
    return remap_keys(input, fn key, value: Key(0, key.to_string()))

export fn second_bound_keys() fn(fn(Int, Int) Key) Map[Key, Int]:
    var chain_1 = Map[Int, Int]()
    chain_1.add(1, 10)
    chain_1.add(2, 20)
    return chain_1.map_keys[Key]

export fn second_value_transform() Int:
    var input = Map[Key, Int]()
    input.add(Key(5, "original"), 2)

    mapped := remap_values(input, fn key, value: value + 1)
    return mapped.get_or(Key(5, "different"), 0)
